@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix mm: <http://data.ardoq.com/meta-model/> .
@prefix common: <http://data.ardoq.com/model/common/> .

#####################################################
# Common elements used throughout Ardoq.
# Part of the general vocabulary, but not the very
# basic structures described in vocab.ttl
#####################################################

common:User a owl:Class ;
            rdfs:label "User" .

common:createdBy a owl:ObjectProperty ;
                 mm:id "createdBy" ;
                 mm:name "createdBy" ;
                 rdfs:label "Created by" .

common:hasTag a owl:ObjectProperty ;
              mm:id "tags" ;
              mm:name "tags" ;
              rdfs:label "Tags" .

common:lastModifiedBy a owl:ObjectProperty ;
                      mm:id "lastModifiedBy" ;
                      mm:name "lastModifiedBy" ;
                      rdfs:label "Updated by" .

common:parent a owl:ObjectProperty ;
              mm:id "parent" ;
              mm:name "parent" ;
              rdfs:label "ardoq_parent" .

common:workspace a owl:ObjectProperty ;
                 mm:id "workspace" ;
                 mm:name "workspace" ;
                 rdfs:label "Workspace" .


common:rootWorkspace a mm:BuiltInFieldType .
                     rdfs:subPropertyOf mm:Field .
                     rdfs:subClassOf mm:Field .
                     mm:id "rootWorkspace" ;
                     mm:name "rootWorkspace" ;
                     rdfs:label "Workspace" .

common:name a mm:BuiltInFieldType ;
            rdfs:subPropertyOf mm:Field ;
            rdfs:subClassOf mm:Field ;
            mm:id "name" ;
            mm:name "name" ;
            rdfs:label "Name" .

common:id a mm:BuiltInFieldType ;
          rdfs:subPropertyOf mm:Field ;
          rdfs:subClassOf mm:Field ;
          mm:id "id" ;
          mm:name "id" ;
          rdfs:label "Ardoq OID" .

common:description a mm:BuiltInFieldType ;
                   rdfs:subPropertyOf mm:Field ;
                   rdfs:subClassOf mm:Field ;
                   mm:id "description" ;
                   mm:name "description" ;
                   rdfs:label "Description" .

common:componentKey a mm:BuiltInFieldType ;
                    rdfs:subPropertyOf mm:Field ;
                    rdfs:subClassOf mm:Field ;
                    mm:id "component-key" ;
                    mm:name "component-key" ;
                    rdfs:label "Ardoq ID" .

common:created a mm:BuiltInFieldType ;
               rdfs:subPropertyOf mm:Field ;
               rdfs:subClassOf mm:Field ;
               mm:id "created" ;
               mm:name "created" ;
               rdfs:label "Created" .

common:lastUpdated a mm:BuiltInFieldType ;
                   rdfs:subPropertyOf mm:Field ;
                   rdfs:subClassOf mm:Field ;
                   mm:id "lastUpdated" ;
                   mm:name "lastUpdated" ;
                   rdfs:label "Last updated" .

common:color a mm:BuiltInFieldType ;
             rdfs:subPropertyOf mm:Field ;
             rdfs:subClassOf mm:Field ;
             rdfs:label "Default color" ;
             mm:id "color" ;
             mm:name "color" ;
             rdfs:label "Color" .

common:icon a mm:BuiltInFieldType ;
            rdfs:subPropertyOf mm:Field ;
            rdfs:subClassOf mm:Field ;
            mm:id "icon" ;
            mm:name "icon" ;
            rdfs:label "Icon" .

common:image a mm:BuiltInFieldType ;
             rdfs:subPropertyOf mm:Field ;
             rdfs:subClassOf mm:Field ;
             mm:id "image" ;
             mm:name "image" ;
             rdfs:label "Image" .

common:shape a mm:BuiltInFieldType ;
             rdfs:subPropertyOf mm:Field ;
             rdfs:subClassOf mm:Field ;
             mm:id "shape" ;
             mm:name "shape" ;
             rdfs:label "Shape" .
